  function mt103WidgetPreview(kind){if(kind==='quick')return `<div class="mt103-widget-quick">${['coffee','utensils','bus','shopping-bag','house','plus'].map(x=>`<span>${icon(x)}</span>`).join('')}</div>`;if(kind==='budget')return `<small>${esc(mt103T('budgetUsed'))}</small><b>¥3,200 / ¥5,000</b><div class="mt103-meter"><i></i></div>`;if(kind==='recent')return ['−¥88.5','+¥8,000','−¥25','−¥120'].map((x,i)=>`<p class="mt103-widget-line"><span>${['🍜','💰','☕','🛒'][i]}</span><b>${x}</b></p>`).join('');if(['rhythm','trail'].includes(kind))return `<div class="mt103-widget-dots">${Array.from({length:kind==='trail'?28:42},(_,i)=>`<i style="opacity:${[.12,.3,.5,.8][i%4]}"></i>`).join('')}</div>`;if(kind==='net')return `<small>${esc(mt103T('accountTotalBalance'))}</small><b class="mt103-widget-amount">¥82,345.67</b><div class="mt103-widget-chart"></div><p class="mt103-widget-line"><span>${esc(mt103T('totalAssets'))}</span><span>¥102,345.67</span></p><p class="mt103-widget-line"><span>${esc(mt103T('totalLiabilities'))}</span><span>¥20,000</span></p>`;return `<small>${esc(mt103T('widgetTodayExpense'))}</small><b class="mt103-widget-amount">¥88.5</b><p class="mt103-widget-line"><span>${esc(mt103T('widgetMonthExpense'))}</span><span>¥3,200.5</span></p>${kind==='dashboard'?'<div class="mt103-widget-chart"></div>':''}`;}
