  function mt103Modal(){const mode=state.mt103Modal;let title='',body='',actions='';if(mode.startsWith('detail:')){const log=state.mt103Logs.find(x=>x.id===Number(mode.slice(7)));title='['+log.tag+']';body=`<p>时间: 2026-10-25 09:41:00</p><p>级别: ${esc(log.level)}</p><p>平台: ${esc(log.source)}</p><hr><p>${esc(log.message)}</p>${log.error?`<p class="mt103-error">Error: ${esc(log.error)}</p>`:''}${log.stack?`<pre>Stack Trace:\n${esc(log.stack)}</pre>`:''}`;actions=mt103Button('copy','复制','bc-secondary')+mt103Button('close','关闭');}else{const isLog=mode==='clear-logs',storage=['models','apks'].includes(mode),selected=state.mt103Orphans.filter(x=>state.mt103Selected.includes(x.id));title=mt103T(isLog?'logCenterClearConfirmTitle':storage?'storageClearConfirmTitle':'maintenanceOrphanConfirmTitle');body=`<p>${esc(isLog?mt103T('logCenterClearConfirmMessage'):storage?mt103T(mode==='models'?'storageClearAIModelsMessage':'storageClearAPKMessage',{size:mode==='models'?'12.50 MB':'35.00 MB'}):mode.startsWith('delete:')?mt103T('maintenanceOrphanConfirmDeleteOne',{title:state.mt103Orphans.find(x=>x.id===mode.slice(7))?.title||''}):mt103T('maintenanceOrphanConfirmDeleteBatch',{count:selected.length}))}</p>`;actions=mt103Button('close',mt103T('commonCancel'),'bc-secondary')+mt103Button('confirm',mt103T(isLog||storage?'commonConfirm':'commonOk'));}return `<div class="mt103-overlay"><section class="mt103-dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h3>${esc(title)}</h3><div class="mt103-dialog-body">${body}</div><div class="mt103-actions">${actions}</div></section></div>`;}
