  document.addEventListener('input',event=>{const el=event.target;if(!el.matches('[data-mt103-search]'))return;state.mt103Search=el.value;const start=el.selectionStart,end=el.selectionEnd;render();const next=document.querySelector?.('[data-mt103-search]');next?.focus();next?.setSelectionRange(start,end);});
